import{_ as n,c as a,h as e,a as l}from"./app-CRUZYf3H.js";const p={};function t(o,s){return l(),a("div",null,s[0]||(s[0]=[e(`<link rel="stylesheet" href="/css/font-style.css"><h1 id="ollama-modelfile-权威指南" tabindex="-1"><a class="header-anchor" href="#ollama-modelfile-权威指南"><span>Ollama Modelfile 权威指南</span></a></h1><blockquote><p>本指南面向想要在 Ollama 平台上打包、部署与调试模型的开发者与运维人员。涵盖 Modelfile 语法、常用字段、进阶技巧、示例与常见问题排查。内容以实践为导向，兼顾安全与可维护性。</p></blockquote><h2 id="_1-简介-什么是-modelfile" tabindex="-1"><a class="header-anchor" href="#_1-简介-什么是-modelfile"><span>1. 简介：什么是 Modelfile</span></a></h2><p>Modelfile 是用来告诉 Ollama 如何从基础镜像或模型文件构建运行时镜像和服务的声明性配置文件。它类似于 Dockerfile，但专注于 AI 模型的运行参数、模板与推理相关的配置。通过规范化的字段，开发者能指定模型来源、输入输出模板、运行时参数和资源要求。</p><h2 id="_2-modelfile-的基本结构" tabindex="-1"><a class="header-anchor" href="#_2-modelfile-的基本结构"><span>2. Modelfile 的基本结构</span></a></h2><p>一个常见的 Modelfile 通常包含：</p><ul><li>基础镜像或模型来源（FROM）</li><li>模板（TEMPLATE）用于定义系统/用户/assistant 对话上下文的基础结构</li><li>PARAMETER：用于定义可调运行参数（如 temperature、max_tokens、stop 等）</li><li>可选：COPY/INSTALL 步骤（具体实现依平台支持）</li></ul><p>基本示例：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">FROM /opt/model/my-base-model</span>
<span class="line">TEMPLATE <span class="token string">&quot;&quot;</span>&quot;<span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>system</span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .System <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span> <span class="token comment"># system部分结束</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> range .Messages <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span><span class="token punctuation">{</span><span class="token punctuation">{</span> .Role <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .Content <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> end <span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token comment"># user and model 结束</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>assistant <span class="token comment"># model开始</span></span>
<span class="line"><span class="token string">&quot;&quot;</span>&quot;</span>
<span class="line">PARAMETER temperature <span class="token number">0.7</span></span>
<span class="line">PARAMETER max_tokens <span class="token number">1024</span></span>
<span class="line">PARAMETER stop <span class="token string">&quot;&lt;|im_end|&gt;&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>说明：不同 Ollama 版本对 Modelfile 的支持字段可能略有差异，建议在部署前参照你的 Ollama 服务版本文档。</p></blockquote><h2 id="_3-常用字段详解" tabindex="-1"><a class="header-anchor" href="#_3-常用字段详解"><span>3. 常用字段详解</span></a></h2><h3 id="from" tabindex="-1"><a class="header-anchor" href="#from"><span>FROM</span></a></h3><ul><li>指定基础模型路径或镜像，例如一个本地模型目录或系统提供的基础镜像。</li><li>可以是相对路径或绝对路径，视平台而定。</li></ul><h3 id="template" tabindex="-1"><a class="header-anchor" href="#template"><span>TEMPLATE</span></a></h3><ul><li>用于定义对话格式（prompt template）。通常用多行文本包裹，支持占位符如 <code>{{ .System }}</code>, <code>{{ range .Messages }}</code> 等。</li><li>模板决定模型输入怎样被序列化到模型上下文，关系到 token 使用和输出一致性。</li></ul><h3 id="parameter" tabindex="-1"><a class="header-anchor" href="#parameter"><span>PARAMETER</span></a></h3><ul><li>用于定义运行时参数。每一行设置一个键值对。</li><li>常见参数：<code>temperature</code>, <code>top_p</code>, <code>max_tokens</code>, <code>stop</code>, <code>num_beams</code>, <code>repetition_penalty</code> 等。</li><li>值可以是数字、字符串或布尔值，取决于参数类型。</li></ul><h3 id="stop" tabindex="-1"><a class="header-anchor" href="#stop"><span>STOP</span></a></h3><ul><li>有些实现把 stop 作为专门字段。它用于定义输出终止符号或 token 序列，避免生成过长或滥生成。</li></ul><h2 id="_4-模板-template-与停止符-stop" tabindex="-1"><a class="header-anchor" href="#_4-模板-template-与停止符-stop"><span>4. 模板（TEMPLATE）与停止符（STOP）</span></a></h2><ul><li>TEMPLATE 的设计原则：<strong>简洁</strong>、<strong>确定性</strong>、<strong>低 token 消耗</strong>。</li><li>使用系统（system）角色放置指令与安全限制，用户（user）角色放置真实输入。</li><li>在需要保证回答不带额外说明或结束在指定 token 时，配置合适的 <code>stop</code> 参数。</li></ul><p>示例模板（指令风格）：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">TEMPLATE <span class="token string">&quot;&quot;</span>&quot;</span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>system</span>
<span class="line">You are a helpful assistant. Follow instructions precisely.</span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>user</span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .Content <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>assistant</span>
<span class="line"><span class="token string">&quot;&quot;</span>&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>system</span>
<span class="line">You are a helpful assistant. Follow instructions precisely.</span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token comment"># 定义了系统角色内容（system message）。</span></span>
<span class="line"><span class="token comment"># 告诉模型它的身份和行为规范。</span></span>
<span class="line"><span class="token comment"># 这部分通常用于放安全策略、人格设定、任务边界等。</span></span>
<span class="line"><span class="token comment"># 这段相当于：“你是一个乐于助人的助手，严格按指令办事。”</span></span>
<span class="line"></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>user <span class="token comment"># 这里制定了必须是user，也可以是Role</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .Content <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token comment"># 这一段表示用户输入的内容。</span></span>
<span class="line"><span class="token comment"># {{ .Content }} 是一个变量，会被 Ollama 在运行时替换为实际的用户问题，例如：“请帮我规划一次日本5日游”。</span></span>
<span class="line"></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>assistant</span>
<span class="line"><span class="token comment"># 这里没有 &lt;|im_end|&gt;，表示模型的回答应接在这里生成。  </span></span>
<span class="line"><span class="token comment"># 模型看到这个提示时，知道该轮到“assistant”说话了。</span></span>
<span class="line"><span class="token comment"># 它会从这里开始生成文字，直到遇到指定的停止标志（stop token，比如 &lt;|im_end|&gt;）。</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>停止符示例：<code>PARAMETER stop &quot;&lt;|im_end|&gt;&quot;</code>，当模型生成完成后，是这个样子的：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>assistant</span>
<span class="line">我推荐您考虑日本北海道或冰岛，这些地方在夏季凉爽宜人，风景优美。</span>
<span class="line">PARAMETER stop <span class="token string">&quot;&lt;|im_end|&gt;&quot;</span></span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>总结：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"></span>
<span class="line">TEMPLATE <span class="token string">&quot;&quot;</span>&quot;<span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>system</span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .System <span class="token punctuation">}</span><span class="token punctuation">}</span>              <span class="token comment"># 系统提示</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> range .Messages <span class="token punctuation">}</span><span class="token punctuation">}</span>       <span class="token comment"># 遍历历史消息</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span><span class="token punctuation">{</span><span class="token punctuation">{</span> .Role <span class="token punctuation">}</span><span class="token punctuation">}</span>     <span class="token comment"># 当前消息角色（user/assistant/system）</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .Content <span class="token punctuation">}</span><span class="token punctuation">}</span>               <span class="token comment"># 当前消息文本</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> end <span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token comment"># {{ range .Messages }} 是一对的</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>assistant        <span class="token comment"># 模型输出起始点</span></span>
<span class="line"><span class="token string">&quot;&quot;</span>&quot;</span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_5-参数-parameter-详解与推荐值" tabindex="-1"><a class="header-anchor" href="#_5-参数-parameter-详解与推荐值"><span>5. 参数（PARAMETER）详解与推荐值</span></a></h2><ul><li><code>temperature</code>（通常 0.0 - 1.0）: 控制随机性；任务需要确定性时设为 0；需要创造性时设高（0.7-1.0）。</li><li><code>top_p</code>（0.0 - 1.0）: 过滤候选 token 的累积概率阈值；与 temperature 联合使用可更好控制输出。</li><li><code>max_tokens</code>：回答最大 token 数；根据上下文与成本设定（例如 512，1024，2048）。</li><li><code>stop</code>：停止序列，字符串或数组形式。</li><li><code>num_beams</code>：用于束搜索，增加确定性但更慢（通常 1-5）。</li><li><code>repetition_penalty</code>：惩罚重复，避免循环生成。</li></ul><p>示例：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">PARAMETER temperature <span class="token number">0.0</span></span>
<span class="line">PARAMETER top_p <span class="token number">0.9</span></span>
<span class="line">PARAMETER max_tokens <span class="token number">512</span></span>
<span class="line">PARAMETER stop <span class="token string">&quot;&lt;|im_end|&gt;&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_6-常见使用场景示例" tabindex="-1"><a class="header-anchor" href="#_6-常见使用场景示例"><span>6. 常见使用场景示例</span></a></h2><h3 id="_6-1-简单推理服务-聊天机器人" tabindex="-1"><a class="header-anchor" href="#_6-1-简单推理服务-聊天机器人"><span>6.1 简单推理服务（聊天机器人）</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">FROM /opt/model/ggml-model</span>
<span class="line">TEMPLATE <span class="token string">&quot;&quot;</span>&quot;<span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>system</span>
<span class="line">You are a helpful assistant.</span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> range .Messages <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span><span class="token punctuation">{</span><span class="token punctuation">{</span> .Role <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .Content <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> end <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>assistant</span>
<span class="line"><span class="token string">&quot;&quot;</span>&quot;</span>
<span class="line">PARAMETER temperature <span class="token number">0.2</span></span>
<span class="line">PARAMETER max_tokens <span class="token number">512</span></span>
<span class="line">PARAMETER stop <span class="token string">&quot;&lt;|im_end|&gt;&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-2-指令微调-sft-后的模型部署" tabindex="-1"><a class="header-anchor" href="#_6-2-指令微调-sft-后的模型部署"><span>6.2 指令微调（SFT）后的模型部署</span></a></h3><p>对 SFT 模型，建议：</p><ul><li>在 TEMPLATE 中明确 system 指令，避免模型偏离调优目标。</li><li>将 SFT 权重放在安全路径并从 <code>FROM</code> 指向。</li></ul><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">FROM /mnt/models/sft-model</span>
<span class="line">TEMPLATE <span class="token string">&quot;&quot;</span>&quot;</span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>system</span>
<span class="line">You are an assistant specialized <span class="token keyword">in</span> legal summarization. Keep answers concise.</span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token string">&quot;&quot;</span>&quot;</span>
<span class="line">PARAMETER temperature <span class="token number">0.0</span></span>
<span class="line">PARAMETER max_tokens <span class="token number">400</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-3-大模型量化与低内存部署" tabindex="-1"><a class="header-anchor" href="#_6-3-大模型量化与低内存部署"><span>6.3 大模型量化与低内存部署</span></a></h3><ul><li>使用量化（8-bit、4-bit）以降低显存需求。</li><li>在 Modelfile 上标注模型已量化且只适用特定后端（例如 GGML、bitsandbytes）。</li></ul><p>并非强制要求，但是是约定</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">FROM /opt/model/llama-7b-q4</span>
<span class="line">PARAMETER quantized <span class="token boolean">true</span> <span class="token comment"># 标注是否量化</span></span>
<span class="line">PARAMETER backend ggml</span>
<span class="line"><span class="token comment"># 这个模型文件是 GGML/GGUF 格式，只能用 CPU 或 llama.cpp 生态的运行时加载。</span></span>
<span class="line"><span class="token comment"># 还有：</span></span>
<span class="line"><span class="token number">1</span>. gguf：新一代 llama.cpp 格式，ggml 的升级版</span>
<span class="line"><span class="token number">2</span>. bitsandbytes：GPU 后端，支持 <span class="token number">8</span>-bit/4-bit 权重</span>
<span class="line"><span class="token number">3</span>. cuda：显式声明使用 NVIDIA CUDA GPU 后端</span>
<span class="line"><span class="token number">4</span>. metal：Mac 平台的 GPU 加速后端</span>
<span class="line"><span class="token number">5</span>. cpu：强制使用 CPU 推理</span>
<span class="line"><span class="token number">6</span>. vulkan：部分系统的跨平台 GPU 后端</span>
<span class="line"><span class="token number">7</span>. tensorrt：NVIDIA 高性能推理引擎</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：量化后测试模型输出一致性，必要时在参数中适当增加 <code>repetition_penalty</code>。</p></blockquote><h2 id="_7-附录-示例-modelfile-热门变体" tabindex="-1"><a class="header-anchor" href="#_7-附录-示例-modelfile-热门变体"><span>7. 附录：示例 Modelfile 热门变体</span></a></h2><h3 id="最小可用-modelfile" tabindex="-1"><a class="header-anchor" href="#最小可用-modelfile"><span>最小可用 Modelfile</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">FROM /opt/model/small-ggml</span>
<span class="line">TEMPLATE <span class="token string">&quot;&quot;</span>&quot;<span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>system</span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .System <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> range .Messages <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span><span class="token punctuation">{</span><span class="token punctuation">{</span> .Role <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .Content <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> end <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>assistant</span>
<span class="line"><span class="token string">&quot;&quot;</span>&quot;</span>
<span class="line">PARAMETER temperature <span class="token number">0.5</span></span>
<span class="line">PARAMETER max_tokens <span class="token number">256</span></span>
<span class="line">PARAMETER stop <span class="token string">&quot;&lt;|im_end|&gt;&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="完整的-demo" tabindex="-1"><a class="header-anchor" href="#完整的-demo"><span>完整的 Demo</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">FROM /opt/model/qwen2.5-1.8b-instruct</span>
<span class="line">TEMPLATE <span class="token string">&quot;&quot;</span>&quot;</span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>system</span>
<span class="line">You are TourTools LP, a professional travel planning assistant.</span>
<span class="line">Your goals:</span>
<span class="line"><span class="token number">1</span>. Always collect the following user information before giving travel suggestions:</span>
<span class="line">   - gender</span>
<span class="line">   - age</span>
<span class="line">   - travel season</span>
<span class="line">   - travel duration</span>
<span class="line">   - budget</span>
<span class="line"><span class="token number">2</span>. Politely refuse unrelated questions and redirect the user back to travel planning topics.</span>
<span class="line"><span class="token number">3</span>. 你仅回答旅游相关的内容，其余的一概回复抱歉，我无法完成</span>
<span class="line"><span class="token number">4</span>. Always end your response with:</span>
<span class="line">   <span class="token string">&#39;感谢您的惠顾，依据您的需求，为您提供如下建议：&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> range .Messages <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span><span class="token punctuation">{</span><span class="token punctuation">{</span> .Role <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> .Content <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_end<span class="token operator">|</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">{</span> end <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token operator">&lt;</span><span class="token operator">|</span>im_start<span class="token operator">|</span><span class="token operator">&gt;</span>assistant</span>
<span class="line"><span class="token string">&quot;&quot;</span>&quot;</span>
<span class="line">PARAMETER temperature <span class="token number">0.3</span></span>
<span class="line">PARAMETER stop <span class="token string">&quot;&lt;|im_end|&gt;&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,50)]))}const c=n(p,[["render",t]]),r=JSON.parse('{"path":"/posts/DeepLearningAndMachineLearning/OllamaModelFile.html","title":"ModelFile 编写指南","lang":"en-US","frontmatter":{"title":"ModelFile 编写指南","description":"ModelFile 编写指南","date":"2026-1-10","timeline":true,"head":[["meta",{"name":"keywords","content":"ModelFile 编写指南"}],["meta",{"name":"description","content":"ModelFile 编写指南"}],["meta",{"name":"author","content":"RobinElysia"}]],"category":["RobinElysia"],"tag":["DL And ML"]},"headers":[{"level":2,"title":"1. 简介：什么是 Modelfile","slug":"_1-简介-什么是-modelfile","link":"#_1-简介-什么是-modelfile","children":[]},{"level":2,"title":"2. Modelfile 的基本结构","slug":"_2-modelfile-的基本结构","link":"#_2-modelfile-的基本结构","children":[]},{"level":2,"title":"3. 常用字段详解","slug":"_3-常用字段详解","link":"#_3-常用字段详解","children":[{"level":3,"title":"FROM","slug":"from","link":"#from","children":[]},{"level":3,"title":"TEMPLATE","slug":"template","link":"#template","children":[]},{"level":3,"title":"PARAMETER","slug":"parameter","link":"#parameter","children":[]},{"level":3,"title":"STOP","slug":"stop","link":"#stop","children":[]}]},{"level":2,"title":"4. 模板（TEMPLATE）与停止符（STOP）","slug":"_4-模板-template-与停止符-stop","link":"#_4-模板-template-与停止符-stop","children":[]},{"level":2,"title":"5. 参数（PARAMETER）详解与推荐值","slug":"_5-参数-parameter-详解与推荐值","link":"#_5-参数-parameter-详解与推荐值","children":[]},{"level":2,"title":"6. 常见使用场景示例","slug":"_6-常见使用场景示例","link":"#_6-常见使用场景示例","children":[{"level":3,"title":"6.1 简单推理服务（聊天机器人）","slug":"_6-1-简单推理服务-聊天机器人","link":"#_6-1-简单推理服务-聊天机器人","children":[]},{"level":3,"title":"6.2 指令微调（SFT）后的模型部署","slug":"_6-2-指令微调-sft-后的模型部署","link":"#_6-2-指令微调-sft-后的模型部署","children":[]},{"level":3,"title":"6.3 大模型量化与低内存部署","slug":"_6-3-大模型量化与低内存部署","link":"#_6-3-大模型量化与低内存部署","children":[]}]},{"level":2,"title":"7. 附录：示例 Modelfile 热门变体","slug":"_7-附录-示例-modelfile-热门变体","link":"#_7-附录-示例-modelfile-热门变体","children":[{"level":3,"title":"最小可用 Modelfile","slug":"最小可用-modelfile","link":"#最小可用-modelfile","children":[]},{"level":3,"title":"完整的 Demo","slug":"完整的-demo","link":"#完整的-demo","children":[]}]}],"git":{"updatedTime":1768057435000,"contributors":[{"name":"qwp_p","username":"","email":"qwp20060309@outlook.com","commits":3}],"changelog":[{"hash":"beb27dce9507e45214206d111b057072387e547f","time":1768057435000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"docs: update documentation headings and structure"},{"hash":"d8b619b6210a7978a63cc8f79cdfc4e55676d4f5","time":1768056600000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"docs(posts): rename DL folder to DeepLearningAndMachineLearning and update tags"},{"hash":"bb725b7d3fadc33e5a1844639eaea62a7858b38c","time":1768056006000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"docs(guide): add comprehensive guides for Ollama ModelFile and Linux regex usage"}]},"filePathRelative":"posts/DeepLearningAndMachineLearning/OllamaModelFile.md","excerpt":"<link rel=\\"stylesheet\\" href=\\"/css/font-style.css\\">\\n<h1>Ollama Modelfile 权威指南</h1>\\n<blockquote>\\n<p>本指南面向想要在 Ollama 平台上打包、部署与调试模型的开发者与运维人员。涵盖 Modelfile 语法、常用字段、进阶技巧、示例与常见问题排查。内容以实践为导向，兼顾安全与可维护性。</p>\\n</blockquote>\\n<h2>1. 简介：什么是 Modelfile</h2>\\n<p>Modelfile 是用来告诉 Ollama 如何从基础镜像或模型文件构建运行时镜像和服务的声明性配置文件。它类似于 Dockerfile，但专注于 AI 模型的运行参数、模板与推理相关的配置。通过规范化的字段，开发者能指定模型来源、输入输出模板、运行时参数和资源要求。</p>"}');export{c as comp,r as data};
